  // body[start] === '['
  let i = start + 1;
  let negated = false;
  if (i < body.length && (body[i] === '!' || body[i] === '^')) {
    negated = true;
    i += 1;
  }
  let closed = false;
  let first = true;
  while (i < body.length) {
    const c = body[i];
    if (c === '\\') {
      if (i + 1 >= body.length) fail('trailing lone backslash in pattern');
      const next = body[i + 1];
      if (!ESCAPABLE.has(next)) fail('cannot escape ' + next);
      i += 2;
      first = false;
      continue;
    }
    if (c === ']' && !first) {
      closed = true;
      i += 1;
      break;
    }
    i += 1;
    first = false;
  }
  if (!closed) fail('unclosed [ in pattern');
  return i;
}

function parsePattern(pattern) {
  let negated = false;
  let body = pattern;
  if (body.startsWith('!')) {
    negated = true;
    body = body.slice(1);
  }
  const segments = [];
  let cur = [];
  for (let i = 0; i < body.length; i++) {
    const c = body[i];
    if (c === '/') {
      segments.push(cur);
      cur = [];
    } else {
      cur.push(c);
    }
  }
  segments.push(cur);
  return {negated, segments: segments.map(parseSegment)};
