function parseSegment(chars) {
  // Build a list of parts: {type:'lit',ch} | {type:'any'} | {type:'star'} | {type:'class',negated,items}
  const parts = [];
  let i = 0;
  while (i < chars.length) {
    const c = chars[i];
    if (c === '\\') {
      parts.push({type: 'lit', ch: chars[i + 1]});
      i += 2;
    } else if (c === '?') {
      parts.push({type: 'any'});
      i += 1;
    } else if (c === '*') {
      // Collapse consecutive stars (but ** is handled at segment level)
      let j = i;
      while (j < chars.length && chars[j] === '*') j++;
      parts.push({type: 'star'});
      i = j;
    } else if (c === '[') {
      const {end, negated, items} = parseClass(chars, i);
      parts.push({type: 'class', negated, items});
