import {selectPaths} from './glob-select.js';
import assert from 'node:assert/strict';
import {execFileSync, spawnSync} from 'node:child_process';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';

// Task example
assert.deepEqual(selectPaths(['a.js','b.js','x/c.js'],['**/*.js','!b.js']),
  {selected:['a.js','x/c.js'],decisions:[
    {path:'a.js',included:true,pattern:0},
    {path:'b.js',included:false,pattern:1},
    {path:'x/c.js',included:true,pattern:0}]});

// ** matches zero or more whole segments
assert.deepEqual(selectPaths(['a/b','a/x/b','a/x/y/b','a','b'],['a/**/b']).selected,
  ['a/b','a/x/b','a/x/y/b']);

// ? matches exactly one char
assert.deepEqual(selectPaths(['ab','a','abc'],['a?']).selected, ['ab']);

// consecutive stars collapse to one star (within a segment)
assert.deepEqual(selectPaths(['abc','a','x'],['a***c']).selected, ['abc']);

// character class basics
assert.deepEqual(selectPaths(['ax','bx','cx','dx'],['[abc]x']).selected, ['ax','bx','cx']);
assert.deepEqual(selectPaths(['ax','bx','cx','dx'],['[^abc]x']).selected, ['dx']);
assert.deepEqual(selectPaths(['ax','bx','cx','dx'],['[!abc]x']).selected, ['dx']);

// ] in first position is literal
assert.deepEqual(selectPaths([']x','ax'],['[]]x']).selected, [']x']);

// ranges and literal dashes
assert.deepEqual(selectPaths(['ax','bx','cx','dx','ex'],['[a-c]x']).selected, ['ax','bx','cx']);
assert.deepEqual(selectPaths(['-x','ax'],['[-a]x']).selected, ['-x','ax']);
assert.deepEqual(selectPaths(['ax','-x'],['[a-]x']).selected, ['ax','-x']);

// escapes
assert.deepEqual(selectPaths(['a*b','axb'],['a\\*b']).selected, ['a*b']);
assert.deepEqual(selectPaths(['a?b','axb'],['a\\?b']).selected, ['a?b']);
assert.deepEqual(selectPaths(['a!b','axb'],['a\\!b']).selected, ['a!b']);
assert.deepEqual(selectPaths(['a-b','axb'],['a\\-b']).selected, ['a-b']);
assert.deepEqual(selectPaths(['a[b','axb'],['a\\[b']).selected, ['a[b']);
assert.deepEqual(selectPaths(['a]b','axb'],['a\\]b']).selected, ['a]b']);
assert.deepEqual(selectPaths(['a\\b','axb'],['a\\\\b']).selected, ['a\\b']);

// invalid patterns
assert.throws(() => selectPaths(['a'],['[abc']), Error);
assert.throws(() => selectPaths(['a'],['abc\\']), Error);
assert.throws(() => selectPaths(['a'],['a\\b']), Error);
assert.throws(() => selectPaths(['a'],['a\\/b']), Error);
assert.throws(() => selectPaths(['a'],['!']), Error);

// empty arrays
assert.deepEqual(selectPaths([], ['*.js']), {selected:[],decisions:[]});
assert.deepEqual(selectPaths(['a.js'], []),
  {selected:[],decisions:[{path:'a.js',included:false,pattern:-1}]});

// validation
for (const bad of [['/a'],['a/'],['a//b'],['.'],['..'],['a/./b'],['a/../b'],['a\0b'],['a','a'],[''],['x',null],['a',1]])
  assert.throws(() => selectPaths(bad, ['*']), Error);
assert.throws(() => selectPaths('a', ['*']), Error);
assert.throws(() => selectPaths(['a'], '*'), Error);
assert.throws(() => selectPaths(['a'], ['']), Error);
assert.throws(() => selectPaths(['a'], [null]), Error);
assert.throws(() => selectPaths(null, ['*']), Error);
assert.throws(() => selectPaths(['a'], null), Error);

// frozen inputs, no mutation
const fp = Object.freeze(['a.js']);
const fpat = Object.freeze(['*.js']);
assert.deepEqual(selectPaths(fp, fpat).selected, ['a.js']);
const mp = ['a.js']; const mpat = ['*.js'];
selectPaths(mp, mpat);
assert.deepEqual(mp, ['a.js']); assert.deepEqual(mpat, ['*.js']);

// last matching pattern decides, both directions
assert.deepEqual(selectPaths(['a.js','b.js'],['!a.js','*.js']).selected, ['a.js','b.js']);
assert.deepEqual(selectPaths(['a.js','b.js'],['*.js','!a.js']).selected, ['b.js']);
assert.deepEqual(selectPaths(['a.js'],['!a.js','!b.js']).decisions[0],
  {path:'a.js',included:false,pattern:0});

// * does not cross segments
assert.deepEqual(selectPaths(['a/b','ab'],['a*b']).selected, ['ab']);

// CLI checks
const dir = mkdtempSync(join(tmpdir(), 'glob-select-check-'));
try {
  const good = join(dir, 'good.json');
  writeFileSync(good, JSON.stringify({paths:['a.js','b.js','x/c.js'],patterns:['**/*.js','!b.js'],extra:1}));
  const ok = spawnSync(process.execPath, ['glob-select.js', good], {encoding:'utf8'});
  assert.equal(ok.status, 0, 'CLI exit 0 on success: ' + ok.stderr);
  assert.equal(ok.stderr, '', 'CLI no stderr on success');
  assert.equal(ok.stdout, JSON.stringify({selected:['a.js','x/c.js'],decisions:[
    {path:'a.js',included:true,pattern:0},
    {path:'b.js',included:false,pattern:1},
    {path:'x/c.js',included:true,pattern:0}]}) + '\n');

  const badJson = join(dir, 'bad.json');
  writeFileSync(badJson, '{oops');
  let r = spawnSync(process.execPath, ['glob-select.js', badJson], {encoding:'utf8'});
  assert.equal(r.status, 2); assert.ok(r.stderr.length > 0); assert.equal(r.stdout, '');

  const badShape = join(dir, 'shape.json');
  writeFileSync(badShape, JSON.stringify(['a']));
  r = spawnSync(process.execPath, ['glob-select.js', badShape], {encoding:'utf8'});
  assert.equal(r.status, 2); assert.ok(r.stderr.length > 0); assert.equal(r.stdout, '');

  const badApi = join(dir, 'api.json');
  writeFileSync(badApi, JSON.stringify({paths:['a','a'],patterns:['*']}));
  r = spawnSync(process.execPath, ['glob-select.js', badApi], {encoding:'utf8'});
  assert.equal(r.status, 2); assert.ok(r.stderr.length > 0); assert.equal(r.stdout, '');

  r = spawnSync(process.execPath, ['glob-select.js'], {encoding:'utf8'});
  assert.equal(r.status, 2); assert.ok(r.stderr.length > 0); assert.equal(r.stdout, '');

  r = spawnSync(process.execPath, ['glob-select.js', 'no-such-file.json'], {encoding:'utf8'});
  assert.equal(r.status, 2); assert.ok(r.stderr.length > 0); assert.equal(r.stdout, '');

  // importing must not run the CLI
  const imp = spawnSync(process.execPath, ['-e', "import('./glob-select.js').then(()=>{})"], {encoding:'utf8'});
  assert.equal(imp.status, 0, 'import must not run CLI: ' + imp.stderr);
  assert.equal(imp.stdout, '');
} finally {
  rmSync(dir, {recursive: true, force: true});
}

console.log('check-contract: all assertions passed');

