const ESCAPABLE = new Set(['\\', '*', '?', '[', ']', '!', '-']);

function fail(message) {
  throw new Error(message);
}

function validatePaths(paths) {
  if (!Array.isArray(paths)) fail('paths must be an array');
  const seen = new Set();
  for (const p of paths) {
    if (typeof p !== 'string' || p.length === 0) fail('paths must be nonempty strings');
    if (p.includes('\0')) fail('path must not contain NUL');
    if (p.startsWith('/') || p.endsWith('/')) fail('path must not start or end with /');
    for (const seg of p.split('/')) {
      if (seg === '' || seg === '.' || seg === '..') fail('invalid path segment');
    }
    if (seen.has(p)) fail('paths must be unique');
    seen.add(p);
  }
}

function validatePatterns(patterns) {
  if (!Array.isArray(patterns)) fail('patterns must be an array');
  for (const pat of patterns) {
    if (typeof pat !== 'string' || pat.length === 0) fail('patterns must be nonempty strings');
    let body = pat;
    if (body.startsWith('!')) {
      if (body.length === 1) fail('negation pattern body must be nonempty');
      body = body.slice(1);
    }
    validatePatternBody(body);
  }
}

function validatePatternBody(body) {
  let i = 0;
  while (i < body.length) {
    const c = body[i];
    if (c === '\\') {
      if (i + 1 >= body.length) fail('trailing lone backslash in pattern');
      const next = body[i + 1];
      if (!ESCAPABLE.has(next)) fail('cannot escape ' + next);
      i += 2;
    } else if (c === '[') {
      i = validateClass(body, i);
    } else {
      i += 1;
    }
  }
}

function validateClass(body, start) {
  // body[start] === '['
  let i = start + 1;
  if (i < body.length && (body[i] === '!' || body[i] === '^')) {
    i += 1;
  }
  let closed = false;
  let first = true;
  while (i < body.length) {
    const c = body[i];
    if (c === '\\') {
      if (i + 1 >= body.length) fail('trailing lone backslash in pattern');
      const next = body[i + 1];
      if (!ESCAPABLE.has(next)) fail('cannot escape ' + next);
      i += 2;
      first = false;
      continue;
    }
    if (c === ']' && !first) {
      closed = true;
      i += 1;
      break;
    }
    i += 1;
    first = false;
  }
  if (!closed) fail('unclosed [ in pattern');
  return i;
}

function parseClass(chars, start) {
  // chars[start] === '['
  let i = start + 1;
  let negated = false;
  if (i < chars.length && (chars[i] === '!' || chars[i] === '^')) {
    negated = true;
    i += 1;
  }
  const items = [];
  let first = true;
  while (i < chars.length) {
    const c = chars[i];
    if (c === '\\') {
      items.push({type: 'lit', ch: chars[i + 1]});
      i += 2;
      first = false;
      continue;
    }
    if (c === ']' && !first) {
      i += 1;
      break;
    }
    // Check for range: c - d (d must not be ']')
    if (i + 2 < chars.length && chars[i + 1] === '-' && chars[i + 2] !== ']') {
      items.push({type: 'range', lo: c, hi: chars[i + 2]});
      i += 3;
    } else {
      items.push({type: 'lit', ch: c});
      i += 1;
    }
    first = false;
  }
  return {end: i, negated, items};
}

function parseSegment(raw) {
  // Build a list of parts
  const parts = [];
  let i = 0;
  while (i < raw.length) {
    const c = raw[i];
    if (c === '\\') {
      parts.push({type: 'lit', ch: raw[i + 1]});
      i += 2;
    } else if (c === '?') {
      parts.push({type: 'any'});
      i += 1;
    } else if (c === '*') {
      let j = i;
      while (j < raw.length && raw[j] === '*') j++;
      parts.push({type: 'star'});
      i = j;
    } else if (c === '[') {
      const {end, negated, items} = parseClass(raw, i);
      parts.push({type: 'class', negated, items});
      i = end;
    } else {
      parts.push({type: 'lit', ch: c});
      i += 1;
    }
  }
  return parts;
}

function classMatches(items, negated, ch) {
  let matched = false;
  for (const item of items) {
    if (item.type === 'lit') {
      if (item.ch === ch) { matched = true; break; }
    } else if (item.type === 'range') {
      if (ch >= item.lo && ch <= item.hi) { matched = true; break; }
    }
  }
  return negated ? !matched : matched;
}

function segmentMatches(parts, seg) {
  const n = parts.length;
  const m = seg.length;
  const dp = Array.from({length: n + 1}, () => new Array(m + 1).fill(false));
  dp[n][m] = true;
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m; j >= 0; j--) {
      const p = parts[i];
      if (p.type === 'star') {
        dp[i][j] = dp[i + 1][j] || (j < m && dp[i][j + 1]);
      } else if (j < m) {
        const ch = seg[j];
        if (p.type === 'lit') {
          dp[i][j] = p.ch === ch && dp[i + 1][j + 1];
        } else if (p.type === 'any') {
          dp[i][j] = dp[i + 1][j + 1];
        } else if (p.type === 'class') {
          dp[i][j] = classMatches(p.items, p.negated, ch) && dp[i + 1][j + 1];
        }
      }
    }
  }
  return dp[0][0];
}

function parsePatternFull(pattern) {
  let negated = false;
  let body = pattern;
  if (body.startsWith('!')) {
    negated = true;
    body = body.slice(1);
  }
  const rawSegs = body.split('/');
  const segments = rawSegs.map(raw => {
    if (raw === '**') {
      return {isDoubleStar: true, parts: null};
    }
    return {isDoubleStar: false, parts: parseSegment(raw)};
  });
  return {negated, segments};
}

function patternMatches(parsed, path) {
  const patSegs = parsed.segments;
  const pathSegs = path.split('/');
  const n = patSegs.length;
  const m = pathSegs.length;
  const dp = Array.from({length: n + 1}, () => new Array(m + 1).fill(false));
  dp[n][m] = true;
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m; j >= 0; j--) {
      const seg = patSegs[i];
      if (seg.isDoubleStar) {
        let ok = false;
        for (let k = j; k <= m; k++) {
          if (dp[i + 1][k]) { ok = true; break; }
        }
        dp[i][j] = ok;
      } else if (j < m) {
        dp[i][j] = segmentMatches(seg.parts, pathSegs[j]) && dp[i + 1][j + 1];
      }
    }
  }
  return dp[0][0];
}

export function selectPaths(paths, patterns) {
  validatePaths(paths);
  validatePatterns(patterns);
  const parsed = patterns.map(parsePatternFull);
  const decisions = [];
  const selected = [];
  for (const path of paths) {
    let included = false;
    let deciding = -1;
    for (let i = 0; i < parsed.length; i++) {
      if (patternMatches(parsed[i], path)) {
        included = !parsed[i].negated;
        deciding = i;
      }
    }
    decisions.push({path, included, pattern: deciding});
    if (included) selected.push(path);
  }
  return {selected, decisions};
}

// CLI
import {readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import process from 'node:process';

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    process.stderr.write('usage: node glob-select.js INPUT_JSON_FILE\n');
    process.exit(2);
  }
  let raw;
  try {
    raw = readFileSync(args[0], 'utf8');
  } catch {
    process.stderr.write('cannot read input file\n');
    process.exit(2);
  }
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    process.stderr.write('invalid JSON\n');
    process.exit(2);
  }
  if (data === null || Array.isArray(data) || typeof data !== 'object') {
    process.stderr.write('input must be a non-null, non-array object\n');
    process.exit(2);
  }
  try {
    const result = selectPaths(data.paths, data.patterns);
